python3 -c "
import json
covered = set('∀∃→¬∧∨↔⊤⊥⊕')
syms = set()
with open('/root/solver-trace-ablation/data/proofwriter_fol_100.jsonl') as f:
    for line in f:
        d = json.loads(line)
        for p in d['fol_premises']:
            for c in p:
                if not c.isascii() and c not in covered:
                    syms.add(c)
        for c in d['fol_conclusion']:
            if not c.isascii() and c not in covered:
                syms.add(c)
print('uncovered:', sorted(syms) if syms else 'NONE')
"
